.hero{ position:relative; height:340vh; }

.herostage{
  position:sticky; top:0; height:100vh; overflow:hidden;
  display:flex; align-items:center; justify-content:center;
}

.herostage canvas{
  position:absolute; inset:0;
  width:100%; height:100%;
  object-fit:cover;
  opacity:.34;
}

.herostage::after{
  content:''; position:absolute; inset:0; pointer-events:none;
  background:
    radial-gradient(120% 90% at 50% 40%, transparent 0%, rgba(8,8,8,.55) 55%, #080808 100%),
    linear-gradient(180deg, rgba(8,8,8,.9) 0%, transparent 22%, transparent 70%, #080808 100%);
}

.heroinner{ position:relative; z-index:2; text-align:center; }

(function () {
'use strict';

const FRAME_COUNT = 80;
const framePath = i => 'assets/hero/f' + String(i).padStart(3,'0') + '.jpg';

const hero   = document.getElementById('hero');
const canvas = document.getElementById('heroframes');
if (!hero || !canvas) return;

const images = new Array(FRAME_COUNT).fill(null);
let ctx = null, lastDrawn = -1, ticking = false;

canvas.width  = 900;
canvas.height = 506;
ctx = canvas.getContext('2d', { alpha:false });
ctx.fillStyle = '#080808';
ctx.fillRect(0, 0, canvas.width, canvas.height);

function load(i){
  return new Promise(resolve => {
    const img = new Image();
    img.onload  = () => { images[i] = img; resolve(img); };
    img.onerror = () => resolve(null);
    img.src = framePath(i + 1);
  });
}

function nearestLoaded(i){
  if (images[i]) return images[i];
  for (let d = 1; d < FRAME_COUNT; d++){
    if (images[i-d]) return images[i-d];
    if (images[i+d]) return images[i+d];
  }
  return null;
}

function draw(i){
  const img = nearestLoaded(i);
  if (!img) return;
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
}

function update(){
  ticking = false;
  const rect = hero.getBoundingClientRect();
  if (rect.height === 0) return;
  const total = rect.height - window.innerHeight;
  const progress = total <= 0 ? 0 : Math.min(1, Math.max(0, -rect.top / total));
  const i = Math.min(FRAME_COUNT - 1, Math.round(progress * (FRAME_COUNT - 1)));
  if (i !== lastDrawn){ lastDrawn = i; draw(i); }
}

function onScroll(){
  if (!ticking){ ticking = true; requestAnimationFrame(update); }
}

window.addEventListener('scroll', onScroll, { passive:true });
window.addEventListener('resize', () => { lastDrawn = -1; update(); }, { passive:true });
onScroll();

})();

async function preload(){
  await load(0);
  draw(0);

  const CONCURRENCY = 6;
  let next = 1;
  await Promise.all(new Array(CONCURRENCY).fill(0).map(async () => {
    while (next < FRAME_COUNT){
      const i = next++;
      await load(i);
      if (i === lastDrawn) draw(i);
    }
  }));
  update();
}
preload();
